def _section(reference):
    doi=reference.get('DOI','10.1016/j.cell.2017.05.024')
    if not isinstance(doi,str) or not re.fullmatch(r'10\.[0-9]{4,9}/[A-Za-z0-9._;/()\-]+',doi):
        raise ValueError('Explicit safe DOI reference required')
    cells=[]
    for case,label in (('TIS','TIS · f35'),('C1','중앙 y=0 · 단일 전극쌍')):
        for metric,title in (('rms3000','3000 Hz carrier 벡터 RMS'),('rms3030','3030 Hz carrier 벡터 RMS'),('am','Δf=30 Hz envelope 변조깊이')):
            cells.append('<article class="paper-cell"><h4>'+label+' · '+title+'</h4><canvas class="paper-map" id="paper-map-'+case+'-'+metric+'" aria-label="'+label+' '+title+' 공간 분포"></canvas></article>')
    legends=''.join('<div class="paper-colorbox"><b id="paper-range-'+m+'"></b><div class="paper-bar"></div><div class="paper-ticks" id="paper-ticks-'+m+'"></div></div>'for m in ('rms3000','rms3030','am'))
    waves=[]
    for point,label in (('surface','(i) 표층 실제 native 셀'),('target','(ii) 목표 깊이 실제 native 셀')):
        for case,name in (('TIS','TIS · f35'),('C1','중앙 C1')):
            waves.append('<article class="paper-cell"><h4>'+label+' · '+name+'</h4><canvas class="paper-wave" id="paper-wave-'+case+'-'+point+'" aria-label="'+label+' '+name+' 실제 합성 파형과 해석적 envelope"></canvas><p class="paper-caption" id="paper-wave-'+case+'-'+point+'-caption"></p></article>')
    return '''<section id="paper-figure" aria-label="논문의 carrier와 envelope 설명 방식을 참고한 전기장 비교">
<div class="paper-kicker">CARRIER → WAVEFORM / ENVELOPE → DIRECTIONAL MODULATION</div>
<h2>전극에서 깊이까지: carrier와 TIS 변조를 나눠 보는 전기장 그림</h2>
<p class="paper-intro">Grossman 등(Cell, 2017)의 Fig.1–2가 보여주는 <b>carrier 분포 → 서로 다른 위치의 합성 파형 → 변조 분포</b>의 설명 순서를 현재 계산 데이터에 적용했습니다. 아래 그림은 이 연구의 native 복소 전기장으로 새로 그린 것입니다.</p>
<div class="paper-controls"><label>공통 native 단면<select id="paper-plane"></select></label><label>변조와 파형의 고정 방향 n<select id="paper-direction"><option value="x">x 방향</option><option value="y">y 방향</option><option value="z">깊이 z 방향</option></select></label><label>공간 지도 색 변환<select id="paper-color"><option value="log">log1p · 전체 범위 / 깊은 세부</option><option value="linear">선형 · 전체 범위</option></select></label><label>파형 시간 창<select id="paper-window"><option value="100">100 ms · 30 Hz envelope</option><option value="2">2 ms · carrier 확대</option></select></label></div>
<p id="paper-mode-caption" class="paper-caption"></p>
<h3 class="paper-panel-title"><span class="paper-panel-letter">A</span>실제 전극 배치와 측정 위치</h3>
<div class="paper-layouts"><article class="paper-cell"><h4>TIS · 실제 rounded 4패드 / 독립 2출력 / common GND / 50 Ω</h4><canvas id="paper-layout-TIS" class="paper-layout" aria-label="TIS 실제 상면 전극 배치"></canvas></article><article class="paper-cell"><h4>C1 · 실제 정방형 2패드 / 독립 1출력 / 귀환 포함 / 50 Ω</h4><canvas id="paper-layout-C1" class="paper-layout" aria-label="C1 실제 중앙 상면 전극 배치"></canvas></article></div>
<p class="paper-caption">중앙 점선 원은 r≤5 mm 목표의 수평 투영입니다. 실제 목표는 깊이15–20 mm의 부피입니다. 두 경우의 형상·총 접촉면적이 다르므로 TIS 방식만의 인과 효과로 해석하지 않습니다. <a href="#field-shape">기존 순간 벡터·전극/ROI 등각 그림 보기 ↓</a></p>
<h3 class="paper-panel-title"><span class="paper-panel-letter">B</span>두 carrier의 RMS와 고정방향 변조 분포</h3>
<p id="paper-plane-caption" class="paper-caption"></p><div class="paper-grid">'''+''.join(cells)+'''</div><div class="paper-colors">'''+legends+'''</div>
<div id="paper-hover" class="paper-hover">공간 지도에 마우스를 올리면 색 변환 전 실제 표시값, 좌표와 native 셀 ID를 표시합니다.</div>
<p class="paper-caption"><b>Carrier RMS</b>는 3성분 벡터의 RMS이고, <b>고정방향 envelope 변조깊이(AM)</b>는 n·E의 두 peak phasor 진폭으로 계산한 2 min(|n·E₃₀₀₀|, |n·E₃₀₃₀|)입니다. Δf=30 Hz는 envelope 변화의 주파수이며 선형 전기장 자체의 30 Hz Fourier 성분이 아닙니다. n은 공간 전체에서 같은 방향이며 기존 2074표본방향 maxTIS와 다릅니다. C1은 3030 Hz가 없어 AM=0이지만 3000 Hz 전기장 RMS는 0이 아닙니다. log1p 색 변환은 log(1 + 값/(1 V/m))이며 tick은 원 V/m입니다. 네 carrier RMS 지도는 주파수·경우 전체에서 하나의 공통 무클리핑 범위를 쓰고, envelope 변조깊이는 두 경우에 공통인 별도 범위를 씁니다.</p>
<h3 class="paper-panel-title"><span class="paper-panel-letter">C</span>표층과 목표 깊이의 실제 합성 파형 및 envelope</h3>
<p id="paper-points" class="paper-caption"></p><div class="paper-legend"><span style="--line:#aab4bd">3000 Hz 성분</span><span style="--line:#80abc5">3030 Hz 성분</span><span style="--line:#ba442e">실제 합성 Eₙ(t)</span><span style="--line:#253c4a">해석적 ±envelope (점선)</span></div><div class="paper-waves">'''+''.join(waves)+'''</div>
<p class="paper-caption">파형은 위 단면·고정 방향 선택과 같은 복소 기저를 사용합니다. 두 표본 위치는 중앙 XZ 단면의 x≈0, 요청 깊이2.5/17.5 mm에 가장 가까운 실제 native 셀로 고정되며 위 xyz가 실제 위치입니다. 표시 단면에 위치가 포함될 때 (i)/(ii)를 지도에 표시합니다. 각 위치에서 TIS와 C1의 파형 y축은 공통이며, 표층과 깊은 위치의 y축은 각각 따로 표시합니다. 이는 <b>전기장 파형</b>으로 5 mm 차동 프로브 전위차가 아닙니다. 기존 probe 간격은 변경하지 않습니다.</p>
<h3 class="paper-panel-title"><span class="paper-panel-letter">D</span>계산된 선 프로파일과 보존된 부피 ROI 통계</h3>
<div class="paper-legend"><span style="--line:#c06f22">TIS · f35</span><span style="--line:#217aa5">중앙 y=0 · C1</span></div><div class="paper-profiles"><article class="paper-cell"><h4>고정방향 AM [V/m] · 절대값</h4><canvas id="paper-profile-am" class="paper-profile" aria-label="고정방향 변조의 실제 native 선 프로파일"></canvas></article><article class="paper-cell"><h4>두 carrier 전체 벡터 RMS [V/m] · 절대값</h4><canvas id="paper-profile-rms" class="paper-profile" aria-label="carrier RMS의 실제 native 선 프로파일"></canvas></article></div>
<p id="paper-profile-caption" class="paper-caption"></p><div class="paper-scroll"><table><thead><tr><th>목표 r≤5 mm·깊이15–20 mm / 기존 Float64 통계</th><th>mean [V/m]</th><th>P10 [V/m]</th><th>ROI 에너지 RMS [V/m]</th></tr></thead><tbody id="paper-roi-body"></tbody></table></div>
<p class="paper-caption">고정방향 AM의 새 부피 mean/P10은 계산하지 않았습니다. 표의 TIS maxTIS는 기존 2074표본방향 검색 결과를 보존한 별도 물리량입니다. 새 파형·단면·선 프로파일은 Float32 표시 샘플이며 기존 Float64 전체 부피 검증을 대체하지 않습니다.</p>
<div class="paper-readout"><b>논문과 현재 모델의 차이.</b> 논문의 단순 saline 팬텀(D50 mm·두께10 mm) 및 절연 전원 구성과 달리 현재는 D50 mm·총깊이25.1 mm의 SC/dermis/fat/muscle 층 모델, 두 출력·공통 GND·50 Ω입니다. 논문의 그림 양식을 참고한 것이며 논문 조건 재현·신경 활성화·안전성 검증을 뜻하지 않습니다. 층 경계와 표면의 큰 전기장을 깊이 집중으로 해석하지 않습니다.</div>
<p id="paper-status" class="paper-status">기존 검증된 native 벡터 화면을 기다리는 중…</p><details><summary>논문 출처 · 물리량 정의 · 검증 범위</summary><pre id="paper-proofs"></pre></details>
<p class="paper-ref">참고: Grossman et al., <i>Noninvasive Deep Brain Stimulation via Temporally Interfering Electric Fields</i>, Cell 169 (2017), Fig.1A–C / Fig.2 / Fig.S2–S3. DOI: <a href="https://doi.org/'''+html.escape(doi,quote=True)+'''">'''+html.escape(doi)+'''</a>. 논문 이미지·원문을 이 GUI에 복제하지 않았습니다. 기존 수렴 실패·접촉 불확실성·실험 미검증 상태는 유지합니다.</p>
</section>'''


def render(base_html, payload):
    """Prepend one explanatory section; embed only paper reference/proofs metadata."""
    if not isinstance(base_html,str) or base_html.count('<main>')!=1 or base_html.count('</body>')!=1 or base_html.count('</style>')!=1:
        raise ValueError('One frozen main/body/style insertion anchor required')
    if 'id="paper-figure"' in base_html or 'window.task1FieldShape' not in base_html:
        raise ValueError('One previously completed native-vector GUI required')
    reference=payload.get('paper_reference')
    proofs=payload.get('paper_proofs')
    if not isinstance(reference,dict) or not isinstance(proofs,dict) or proofs.get('new_PDE')!=0:
        raise ValueError('Explicit cited reference and reuse-only proof required')
    small=dict(paper_reference=reference,paper_proofs=proofs)
    q=json.dumps(small,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('<','\\u003c')
    if len(q.encode())>256*1024:
        raise ValueError('Paper metadata must not duplicate native payload or paper text')
    csp=re.search(r'script-src ([^;\"]+)',base_html)
    if csp is None:raise ValueError('Existing strict CSP required')
    digest=base64.b64encode(hashlib.sha256(SCRIPT.encode()).digest()).decode()
    result=base_html[:csp.end()]+" 'sha256-"+digest+"'"+base_html[csp.end():]
    result=result.replace('</style>',CSS+'</style>',1)
    result=result.replace('<main>','<main>'+_section(reference),1)
    result=result.replace('</body>','<script id="paper-config" type="application/json">'+q+'</script><script>'+SCRIPT+'</script></body>',1)
    original=re.findall(r'<script(?:\s[^>]*)?>.*?</script>',base_html,re.S)
    current=re.findall(r'<script(?:\s[^>]*)?>.*?</script>',result,re.S)
    if original!=current[:-2]:raise ValueError('Original packed data or executable scripts changed')
    return result
